"""Build a self-contained Mudlet plugin from independently testable Lua modules."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
VERSION = '0.7.0-beta.4'
MODULES = ['engine', 'tactics_model', 'integration', 'tactics', 'hud', 'init']


def build(check=False):
    pieces = ['-- Chimera AutoExp 5 / standalone plugin for official Chimera 5.x.\n',
              '-- Generated by build.py. Edit src/chimeraxp/*.lua, then rebuild.\n',
              'local factories, cache = {}, {}\n']
    for name in MODULES:
        source = (ROOT / 'src/chimeraxp' / (name + '.lua')).read_text('utf-8')
        pieces.append('factories["' + name + '"] = function()\n' + source.rstrip() + '\nend\n')
    pieces.append('local function module(name)\n'
                  '    if cache[name] == nil then cache[name] = assert(factories[name], name)() end\n'
                  '    return cache[name]\nend\nreturn module("init")(module)\n')
    bundle = ''.join(pieces).encode('utf-8')
    path = ROOT / 'plugins/chimera_autoexp/init.lua'
    manifest = {'name': 'ChimeraXP', 'schema': 1, 'version': VERSION, 'channel': 'beta',
                'official_chimera': '5.x', 'files': [{'path': 'plugins/chimera_autoexp/init.lua',
                'sha256': hashlib.sha256(bundle).hexdigest()}]}
    manifest_bytes = (json.dumps(manifest, indent=2) + '\n').encode('utf-8')
    if check:
        assert path.read_bytes() == bundle, 'Generated plugin is stale; run python build.py'
        assert (ROOT / 'manifest.json').read_bytes() == manifest_bytes, 'Manifest is stale'
    else:
        path.write_bytes(bundle)
        (ROOT / 'manifest.json').write_bytes(manifest_bytes)


if __name__ == '__main__':
    import sys
    build('--check' in sys.argv)
